#define IN(tab, cp) __uni_in_range(tab, sizeof(tab) / sizeof(*tab), (cp))

int __uni_isalpha(unsigned cp) { return IN(uni_alpha, cp); }
int __uni_isupper(unsigned cp) { return IN(uni_upper, cp); }
int __uni_islower(unsigned cp) { return IN(uni_lower, cp); }
int __uni_ispunct(unsigned cp) { return IN(uni_punct, cp); }
int __uni_isprint(unsigned cp) { return IN(uni_print, cp); }
int __uni_isspace(unsigned cp) { return IN(uni_space, cp); }
int __uni_iscntrl(unsigned cp) { return IN(uni_cntrl, cp); }
int __uni_isblank(unsigned cp) { return IN(uni_blank, cp); }
int __uni_isgraph(unsigned cp) { return IN(uni_graph, cp); }
int __uni_isalnum(unsigned cp) { return IN(uni_alnum, cp); }
int __uni_isdigit(unsigned cp) { return IN(uni_digit, cp); }
int __uni_isxdigit(unsigned cp) { return IN(uni_xdigit, cp); }

/* The NUL advances nothing; everything not listed occupies one column. */
int __uni_width(unsigned cp)
{
	if (cp == 0)
		return 0;
	if (IN(uni_wneg, cp))
		return -1;
	if (IN(uni_w0, cp))
		return 0;
	if (IN(uni_w2, cp))
		return 2;
	return 1;
}

unsigned __uni_toupper(unsigned cp)
{
	return cp + (unsigned)delta_of(uni_toupper,
				       sizeof(uni_toupper) / sizeof(*uni_toupper),
				       cp);
}

unsigned __uni_tolower(unsigned cp)
{
	return cp + (unsigned)delta_of(uni_tolower,
				       sizeof(uni_tolower) / sizeof(*uni_tolower),
				       cp);
}
